package com.careflow.ai.clinical;
import com.careflow.common.exception.BusinessException;import com.fasterxml.jackson.databind.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.scheduling.annotation.Scheduled;import javax.sql.DataSource;import java.time.*;import java.sql.*;import java.util.*;
public class ClinicalStore {
    private final JdbcTemplate jdbc;private final ObjectMapper json;private final ClinicalCipher cipher;private final int days;
    public ClinicalStore(DataSource ds,ObjectMapper json,ClinicalCipher cipher,int days){jdbc=new JdbcTemplate(ds);this.json=json;this.cipher=cipher;this.days=days;}
    public record Source(UUID id,String title,String revision,String department,String url,String content,String hash,String status,boolean synthetic,UUID reviewer,Instant reviewedAt){}
    private Source row(java.sql.ResultSet r,int n)throws SQLException{return new Source(r.getObject("id",UUID.class),r.getString("title"),r.getString("revision"),r.getString("department_code"),r.getString("source_url"),r.getString("content"),r.getString("content_hash"),r.getString("status"),r.getBoolean("synthetic"),r.getObject("reviewer_id",UUID.class),r.getTimestamp("reviewed_at")==null?null:r.getTimestamp("reviewed_at").toInstant());}
    public List<Source> sources(){return jdbc.query("SELECT * FROM ai_guideline_sources ORDER BY created_at DESC LIMIT100".replace("LIMIT100","LIMIT 100"),this::row);}
    public List<Source> eligibleSources(String department,boolean synthetic){return jdbc.query("SELECT * FROM ai_guideline_sources WHERE status='APPROVED' AND department_code=? AND (? OR synthetic=false) ORDER BY created_at DESC",this::row,department,synthetic);}
    public Source source(UUID id){var rows=jdbc.query("SELECT * FROM ai_guideline_sources WHERE id=?",this::row,id);if(rows.isEmpty())throw new BusinessException(404,"Không tìm thấy nguồn hướng dẫn");return rows.getFirst();}
    public Source create(String title,String revision,String department,String url,String content,boolean synthetic,UUID actor){UUID id=UUID.randomUUID();try{jdbc.update("INSERT INTO ai_guideline_sources(id,title,revision,department_code,source_url,content,content_hash,synthetic,imported_by) VALUES (?,?,?,?,?,?,?,?,?)",id,title,revision,department,url,content,com.careflow.ai.voice.VoiceRemoteClient.sha(content),synthetic,actor);}catch(org.springframework.dao.DuplicateKeyException e){throw new BusinessException(409,"Phiên bản nguồn này đã tồn tại");}return source(id);}
    public Source review(UUID id,UUID actor,String expectedHash){var s=source(id);if(!s.hash().equals(expectedHash))throw new BusinessException(409,"Nội dung nguồn đã thay đổi");if(jdbc.update("UPDATE ai_guideline_sources SET status='APPROVED',reviewer_id=?,reviewed_at=now() WHERE id=? AND status='DRAFT' AND imported_by<>?",actor,id,actor)!=1)throw new BusinessException(409,"Nguồn đã được xử lý hoặc người nhập không được tự duyệt");return source(id);}
    public Source retire(UUID id){if(jdbc.update("UPDATE ai_guideline_sources SET status='RETIRED' WHERE id=? AND status<>'RETIRED'",id)!=1)throw new BusinessException(409,"Nguồn không còn hoạt động");return source(id);}
    public void save(UUID id,UUID actor,UUID consultation,UUID parent,String contextHash,JsonNode content,String engine){String binding=id+":"+actor+":"+consultation;jdbc.update("INSERT INTO ai_clinical_interactions(id,actor_id,consultation_id,parent_id,context_hash,content_cipher,engine_id,expires_at) VALUES (?,?,?,?,?,?,?,?)",id,actor,consultation,parent,contextHash,cipher.encrypt(content.toString(),binding),engine,Timestamp.from(Instant.now().plusSeconds(days*86400L)));}
    public JsonNode read(UUID id,UUID actor,UUID consultation){var list=jdbc.queryForList("SELECT consultation_id,content_cipher FROM ai_clinical_interactions WHERE id=? AND actor_id=? AND expires_at>now()",id,actor);if(list.isEmpty())throw new BusinessException(404,"Tương tác đã hết hạn hoặc không thuộc phiên bác sĩ");var row=list.getFirst();if(consultation!=null&&!consultation.equals(row.get("consultation_id")))throw new BusinessException(409,"Tương tác trước không thuộc ca khám này");try{return json.readTree(cipher.decrypt((String)row.get("content_cipher"),id+":"+actor+":"+row.get("consultation_id")));}catch(Exception e){throw new BusinessException(503,"Không đọc được nhật ký AI");}}
    public UUID consultation(UUID id,UUID actor){var ids=jdbc.query("SELECT consultation_id FROM ai_clinical_interactions WHERE id=? AND actor_id=? AND expires_at>now()",(r,n)->r.getObject(1,UUID.class),id,actor);if(ids.isEmpty())throw new BusinessException(404,"Không tìm thấy tương tác");return ids.getFirst();}
    public List<UUID> history(UUID actor,UUID consultation){return jdbc.query("SELECT id FROM ai_clinical_interactions WHERE actor_id=? AND consultation_id=? AND expires_at>now() ORDER BY created_at DESC LIMIT 20",(r,n)->r.getObject(1,UUID.class),actor,consultation);}
    @Scheduled(fixedDelay=60000) public void cleanup(){jdbc.update("DELETE FROM ai_clinical_interactions WHERE expires_at<=now()");}
}
